    /// axis is the "left thumb stick," etc.
    /// </para>
    /// <para>
    /// The value returned by SDL_GetJoystickAxis() is a signed integer (-32768 to 32767) representing the current
    /// position of the axis. It may be necessary to impose certain tolerances on these values to account for jitter.
    /// </para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>See also: <c>SDL_GetNumJoystickAxes</c>.</para>
    /// </remarks>
    /// <param name="axis">the axis to query; the axis indices start at index 0.</param>
    /// <returns>
    /// a 16-bit signed integer representing the current position of the axis or 0 on failure; call SDL_GetError() for
    /// more information.
    /// </returns>
    public short GetAxis(int axis) => Sdl.GetJoystickAxis(this, axis);

    /// <summary>Get the initial state of an axis control on a joystick.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_GetJoystickAxisInitialState</c>.</para>
    /// <para>The state is a value ranging from -32768 to 32767.</para>
    /// <para>The axis indices start at index 0.</para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// </remarks>
    /// <param name="axis">the axis to query; the axis indices start at index 0.</param>
    /// <param name="state">upon return, the initial value is supplied here.</param>
    /// <returns>true if this axis has any initial value, or false if not.</returns>
    public bool GetAxisInitialState(int axis, short* state) => Sdl.GetJoystickAxisInitialState(this, axis, state);

    /// <summary>Get the initial state of an axis control on a joystick.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_GetJoystickAxisInitialState</c>.</para>
    /// <para>The state is a value ranging from -32768 to 32767.</para>
    /// <para>The axis indices start at index 0.</para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// </remarks>
    /// <param name="axis">the axis to query; the axis indices start at index 0.</param>
    /// <param name="state">upon return, the initial value is supplied here.</param>
    /// <returns>true if this axis has any initial value, or false if not.</returns>
    public bool GetAxisInitialState(int axis, out short state) => Sdl.GetJoystickAxisInitialState(this, axis, out state);

    /// <summary>Get the ball axis change since the last poll.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_GetJoystickBall</c>.</para>
    /// <para>
    /// Trackballs can only return relative motion since the last call to SDL_GetJoystickBall(), these motion deltas are
    /// placed into <c>dx</c> and <c>dy</c>.
    /// </para>
    /// <para>Most joysticks do not have trackballs.</para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>See also: <c>SDL_GetNumJoystickBalls</c>.</para>
    /// </remarks>
    /// <param name="ball">the ball index to query; ball indices start at index 0.</param>
    /// <param name="dx">stores the difference in the x axis position since the last poll.</param>
    /// <param name="dy">stores the difference in the y axis position since the last poll.</param>
    /// <returns>true on success or false on failure; call SDL_GetError() for more information.</returns>
    public bool GetBall(int ball, int* dx, int* dy) => Sdl.GetJoystickBall(this, ball, dx, dy);

    /// <summary>Get the ball axis change since the last poll.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_GetJoystickBall</c>.</para>
    /// <para>
    /// Trackballs can only return relative motion since the last call to SDL_GetJoystickBall(), these motion deltas are
    /// placed into <c>dx</c> and <c>dy</c>.
    /// </para>
    /// <para>Most joysticks do not have trackballs.</para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>See also: <c>SDL_GetNumJoystickBalls</c>.</para>
    /// </remarks>
    /// <param name="ball">the ball index to query; ball indices start at index 0.</param>
    /// <param name="dx">stores the difference in the x axis position since the last poll.</param>
    /// <param name="dy">stores the difference in the y axis position since the last poll.</param>
    /// <returns>true on success or false on failure; call SDL_GetError() for more information.</returns>
    public bool GetBall(int ball, out int dx, out int dy) => Sdl.GetJoystickBall(this, ball, out dx, out dy);

    /// <summary>Get the current state of a POV hat on a joystick.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_GetJoystickHat</c>.</para>
    /// <para>The returned value will be one of the <c>SDL_HAT_*</c> values.</para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>See also: <c>SDL_GetNumJoystickHats</c>.</para>
    /// </remarks>
    /// <param name="hat">the hat index to get the state from; indices start at index 0.</param>
    /// <returns>the current hat position.</returns>
    public byte GetHat(int hat) => Sdl.GetJoystickHat(this, hat);

    /// <summary>Get the current state of a button on a joystick.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_GetJoystickButton</c>.</para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>See also: <c>SDL_GetNumJoystickButtons</c>.</para>
    /// </remarks>
    /// <param name="button">the button index to get the state from; indices start at index 0.</param>
    /// <returns>true if the button is pressed, false otherwise.</returns>
    public bool GetButton(int button) => Sdl.GetJoystickButton(this, button);

    /// <summary>Start a rumble effect.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_RumbleJoystick</c>.</para>
    /// <para>
    /// Each call to this function cancels any previous rumble effect, and calling it with 0 intensity stops any
    /// rumbling.
    /// </para>
    /// <para>
    /// This function requires you to process SDL events or call SDL_UpdateJoysticks() to update rumble state.
    /// </para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// </remarks>
    /// <param name="lowFrequencyRumble">
    /// the intensity of the low frequency (left) rumble motor, from 0 to 0xFFFF.
    /// </param>
    /// <param name="highFrequencyRumble">
    /// the intensity of the high frequency (right) rumble motor, from 0 to 0xFFFF.
    /// </param>
    /// <param name="durationMs">the duration of the rumble effect, in milliseconds.</param>
    /// <returns>true, or false if rumble isn't supported on this joystick.</returns>
    public bool Rumble(ushort lowFrequencyRumble, ushort highFrequencyRumble, uint durationMs) => Sdl.RumbleJoystick(this, lowFrequencyRumble, highFrequencyRumble, durationMs);

    /// <summary>Start a rumble effect in the joystick's triggers.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_RumbleJoystickTriggers</c>.</para>
    /// <para>
    /// Each call to this function cancels any previous trigger rumble effect, and calling it with 0 intensity stops any
    /// rumbling.
    /// </para>
    /// <para>
    /// Note that this is rumbling of the _triggers_ and not the game controller as a whole. This is currently only
    /// supported on Xbox One controllers. If you want the (more common) whole-controller rumble, use
    /// SDL_RumbleJoystick() instead.
    /// </para>
    /// <para>
    /// This function requires you to process SDL events or call SDL_UpdateJoysticks() to update rumble state.
    /// </para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>See also: <c>SDL_RumbleJoystick</c>.</para>
    /// </remarks>
    /// <param name="leftRumble">the intensity of the left trigger rumble motor, from 0 to 0xFFFF.</param>
    /// <param name="rightRumble">the intensity of the right trigger rumble motor, from 0 to 0xFFFF.</param>
    /// <param name="durationMs">the duration of the rumble effect, in milliseconds.</param>
    /// <returns>true on success or false on failure; call SDL_GetError() for more information.</returns>
    public bool RumbleTriggers(ushort leftRumble, ushort rightRumble, uint durationMs) => Sdl.RumbleJoystickTriggers(this, leftRumble, rightRumble, durationMs);

    /// <summary>Update a joystick's LED color.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_SetJoystickLED</c>.</para>
    /// <para>An example of a joystick LED is the light on the back of a PlayStation 4's DualShock 4 controller.</para>
    /// <para>
    /// For joysticks with a single color LED, the maximum of the RGB values will be used as the LED brightness.
    /// </para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// </remarks>
    /// <param name="red">the intensity of the red LED.</param>
    /// <param name="green">the intensity of the green LED.</param>
    /// <param name="blue">the intensity of the blue LED.</param>
    /// <returns>true on success or false on failure; call SDL_GetError() for more information.</returns>
    public bool SetLED(byte red, byte green, byte blue) => Sdl.SetJoystickLED(this, red, green, blue);

    /// <summary>Send a joystick specific effect packet.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_SendJoystickEffect</c>.</para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// </remarks>
    /// <param name="data">the data to send to the joystick.</param>
    /// <param name="size">the size of the data to send to the joystick.</param>
    /// <returns>true on success or false on failure; call SDL_GetError() for more information.</returns>
    public bool SendEffect(void* data, int size) => Sdl.SendJoystickEffect(this, data, size);

    /// <summary>Close a joystick previously opened with SDL_OpenJoystick().</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_CloseJoystick</c>.</para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>See also: <c>SDL_OpenJoystick</c>.</para>
    /// </remarks>
    public void Close() => Sdl.CloseJoystick(this);

    /// <summary>Get the connection state of a joystick.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_GetJoystickConnectionState</c>.</para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// </remarks>
    /// <returns>
    /// the connection state on success or <c>SDL_JOYSTICK_CONNECTION_INVALID</c> on failure; call SDL_GetError() for
    /// more information.
    /// </returns>
    public JoystickConnectionState GetConnectionState() => Sdl.GetJoystickConnectionState(this);

    /// <summary>Get the battery state of a joystick.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_GetJoystickPowerInfo</c>.</para>
    /// <para>
    /// You should never take a battery status as absolute truth. Batteries (especially failing batteries) are delicate
    /// hardware, and the values reported here are best estimates based on what that hardware reports. It's not uncommon
    /// for older batteries to lose stored power much faster than it reports, or completely drain when reporting it has
    /// 20 percent left, etc.
    /// </para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// </remarks>
    /// <param name="percent">
    /// a pointer filled in with the percentage of battery life left, between 0 and 100, or NULL to ignore. This will be
    /// filled in with -1 we can't determine a value or there is no battery.
    /// </param>
    /// <returns>
    /// the current battery state or <c>SDL_POWERSTATE_ERROR</c> on failure; call SDL_GetError() for more information.
    /// </returns>
    public PowerState GetPowerInfo(int* percent) => Sdl.GetJoystickPowerInfo(this, percent);

    /// <summary>Get the battery state of a joystick.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_GetJoystickPowerInfo</c>.</para>
    /// <para>
    /// You should never take a battery status as absolute truth. Batteries (especially failing batteries) are delicate
    /// hardware, and the values reported here are best estimates based on what that hardware reports. It's not uncommon
    /// for older batteries to lose stored power much faster than it reports, or completely drain when reporting it has
    /// 20 percent left, etc.
    /// </para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// </remarks>
    /// <param name="percent">
    /// a pointer filled in with the percentage of battery life left, between 0 and 100, or NULL to ignore. This will be
    /// filled in with -1 we can't determine a value or there is no battery.
    /// </param>
    /// <returns>
    /// the current battery state or <c>SDL_POWERSTATE_ERROR</c> on failure; call SDL_GetError() for more information.
    /// </returns>
    public PowerState GetPowerInfo(out int percent) => Sdl.GetJoystickPowerInfo(this, out percent);

    /// <summary>Query if a joystick has haptic features.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_IsJoystickHaptic</c>.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>See also: <c>SDL_OpenHapticFromJoystick</c>.</para>
    /// </remarks>
    /// <returns>true if the joystick is haptic or false if it isn't.</returns>
    public bool IsHaptic() => Sdl.IsJoystickHaptic(this);

    /// <summary>Open a haptic device for use from a joystick device.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_OpenHapticFromJoystick</c>.</para>
    /// <para>You must still close the haptic device separately. It will not be closed with the joystick.</para>
    /// <para>
    /// When opened from a joystick you should first close the haptic device before closing the joystick device. If not,
    /// on some implementations the haptic device will also get unallocated and you'll be unable to use force feedback
    /// on that device.
    /// </para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>See also: <c>SDL_CloseHaptic</c>, <c>SDL_IsJoystickHaptic</c>.</para>
    /// </remarks>
    /// <returns>
    /// a valid haptic device identifier on success or NULL on failure; call SDL_GetError() for more information.
    /// </returns>
    public Haptic OpenHapticFromJoystick() => Sdl.OpenHapticFromJoystick(this);
}
